package run.ikaros.password; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; @RestController @RequestMapping("/api/v2/password/vaults/{vaultId}/favorites") public class PasswordFavoriteController{private final PasswordFavoriteService service;public PasswordFavoriteController(PasswordFavoriteService s){service=s;}@GetMapping public Flux<PasswordVaultItemView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.list(a,vaultId);}}
